'use strict';
const sellerTabs=[['','Overview'],['products','Products'],['orders','Orders'],['finance','Finances'],['learning','Learning center'],['settings','Store settings']];
const sellerSession={step:1,draft:{},images:[]};
function sellerSave(){try{save();return true}catch{toast('Browser storage is full. Remove some product photos and try again.');return false}}
function sellerOwns(){return state.seller&&state.user&&state.seller.ownerEmail===state.user.email}
function sellerLive(){return sellerOwns()&&state.seller.status==='active'}
function sellerProduct(l){return {id:l.id,name:l.name,brand:l.brand||state.seller.shopName,category:l.category,price:Number(l.price),old:Number(l.old)||Number(l.price),rating:0,reviews:0,stock:l.variants.reduce((s,v)=>s+Number(v.stock),0),image:l.images[0],gallery:l.images.map((src,i)=>({src,full:src,thumb:src,label:i===0?'Main product image':'Product image '+(i+1)})),variants:l.variants.map(v=>v.name),unavailable:l.variants.filter(v=>Number(v.stock)<=0).map(v=>v.name),variantStock:Object.fromEntries(l.variants.map(v=>[v.name,Number(v.stock)])),specs:{Description:l.description,Condition:l.condition,SKU:l.sku},sellerId:state.seller.id,listingStatus:l.status};}
function syncSellerProducts(){for(let i=products.length-1;i>=0;i--)if(products[i].sellerId)products.splice(i,1);if(state.seller?.listings)for(const l of state.seller.listings)products.push(sellerProduct(l));}
syncSellerProducts();
const baseAdd=add;add=function(id,variant){const p=getP(id);if(p?.sellerId&&p.listingStatus!=='active')return toast('This listing is not currently available.');if(p&&!p.variants.includes(variant))return toast('Choose an available variation.');return baseAdd(id,variant)};
const baseProductPage=productPage;productPage=function(id){const p=getP(id);if(p?.sellerId&&p.listingStatus!=='active')return '<div class="crumbs"><a href="#/catalog">Shop</a> / Listing unavailable</div>'+empty('This listing is taking a break','Try another product or come back later.');let html=baseProductPage(id);if(p?.sellerId){const storeName=state.seller?.id===p.sellerId?state.seller.shopName:window.KstoreCloud?.stores?.get(p.sellerId)?.shopName||p.sellerName||p.brand;html=html.replace('Made for your everyday','From '+esc(storeName)).replace('Sold by '+p.brand+' Store','Sold by '+esc(storeName)).replace('<span class="status">Verified partner</span>','<span class="status">Demo seller</span>').replace('Sample review · Demo content','Sample review · Demo content');}return html};
function sellerPage(path){if(path==='/sell')return sellerLanding();if(path==='/seller/onboarding')return sellerOnboarding();if(path.startsWith('/seller/store/'))return sellerStore();if(!sellerOwns())return '<div class="seller-access panel"><span class="eyebrow">KSTORE SELLER CENTER</span><h1>Your next chapter starts here.</h1><p class="muted">Sign in with your demo seller email to manage your store, or start a new seller application.</p><a class="primary" href="#/account">Sign in</a> <a class="secondary" href="#/seller/onboarding">Become a seller</a></div>';if(!sellerLive())return sellerOnboarding();return sellerDashboard(path.split('/')[2]||'')}
function sellerLanding(){return '<div class="seller-breadcrumb">KSTORE FOR BUSINESS</div><section class="seller-hero"><div><span class="eyebrow">YOUR BUSINESS. MORE POSSIBILITIES.</span><h1>Great products deserve<br>a bigger audience.</h1><p>Turn what you sell into what’s next. Build your store, showcase your products, and manage every order in one place.</p><div class="seller-hero-actions"><a class="primary" href="#/seller/onboarding">Start selling →</a><a class="secondary" href="#/seller">Go to seller center</a></div><span class="seller-fine">A guided setup. A space to grow.</span></div><div class="seller-preview-card"><div class="seller-mini-head"><span class="seller-store-icon">'+icon('cart')+'</span><b>Your store, at a glance</b><span class="status">Demo preview</span></div><div class="seller-mini-stat"><small>Everything you need to sell</small><h2>One simple workspace.</h2><p class="muted small">Your products. Your inventory. Your next opportunity.</p></div><div class="seller-preview-bars"><i style="height:28%"></i><i style="height:48%"></i><i style="height:35%"></i><i style="height:70%"></i><i style="height:61%"></i><i style="height:85%"></i><i style="height:100%"></i></div><div class="seller-preview-foot"><span>Product listings</span><span>Order management</span><span>Store insights</span></div></div></section><div class="seller-benefit-grid">'+[['01','Make your products discoverable','Bring your catalog to a marketplace built for everyday shopping.'],['02','Stay in control','Manage photos, variations, prices and stock from your seller center.'],['03','Keep orders moving','See what needs attention and update fulfillment in one place.'],['04','Build with confidence','Start with practical guides, a clear setup checklist and useful insights.']].map(([n,t,d])=>'<article><span>'+n+'</span><h3>'+t+'</h3><p>'+d+'</p></article>').join('')+'</div><section class="seller-how section"><div><span class="eyebrow">FROM IDEA TO STOREFRONT</span><h2>Ready in a few<br>thoughtful steps.</h2><p class="muted">Start small. Learn as you go. Make it yours.</p><a class="primary" href="#/seller/onboarding">Create your store →</a></div><div class="seller-steps">'+[['Create your seller profile','Tell us about your store and how to reach you.'],['Set up your business','Add your operating location and choose a demo payout preference.'],['Learn the essentials','Review the product, order and service guidelines.'],['List your first product','Add photos, price and variations, then preview your listing.']].map(([t,d],i)=>'<div><span>'+(i+1)+'</span><section><h3>'+t+'</h3><p>'+d+'</p></section></div>').join('')+'</div></section><section class="panel faq section"><h2>A few things before you start</h2>'+[['What do I need to open a store?','A store name, seller contact, operating location, product information and a demo payout preference. Business verification and real payout setup require a live seller service.'],['Can I sell products with sizes or colors?','Yes. Each listing can have multiple variations, each with its own stock quantity, and up to six product photos.'],['Are listings shared with other shoppers?','This interactive demo saves listings in this browser. Published listings appear in this browser’s catalog. A shared marketplace requires authenticated server storage.'],['Are there seller fees?','This demo uses a clearly labeled sample 5% commission to illustrate finance calculations. It is not a production pricing agreement.'],['Will this create a real seller account?','No. Onboarding and seller operations are simulated. Do not enter real identity documents, bank account numbers or confidential business information.']].map(([q,a])=>'<details><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'</section><div class="seller-cta"><h2>Your next customer starts with a first step.</h2><a class="primary" href="#/seller/onboarding">Let’s build your store →</a></div>'}
function sellerOnboarding(){if(state.seller&&sellerOwns()&&state.seller.status==='active')return '<div class="seller-access panel"><span class="status">Demo store active</span><h1>'+esc(state.seller.shopName)+' is ready.</h1><p>Head to your seller center to manage products and orders.</p><a class="primary" href="#/seller">Open seller center →</a></div>';if(state.seller&&!sellerOwns())return '<div class="seller-access panel"><h1>A store already exists in this browser.</h1><p>Sign in with its demo seller email to continue. To start fresh, clear your browser demo data from the privacy page.</p><a class="primary" href="#/account">Sign in</a></div>';const d={...state.seller?.application,...sellerSession.draft},step=Number(d.step||sellerSession.step)||1;sellerSession.step=step;sellerSession.draft={...d};const fields=step===1?'<h2>Let’s meet your business.</h2><p class="muted small">Use sample details for this browser-only demo.</p><div class="two-col">'+sellerField('Full name','ownerName',d.ownerName||state.user?.name||'','text','required maxlength="70"')+sellerField('Seller email','email',d.email||state.user?.email||'','email','required')+'</div><div class="two-col">'+sellerField('Phone number','phone',d.phone||'','tel','required pattern="[0-9+ ()-]{9,16}"')+sellerField('Store name','shopName',d.shopName||'','text','required minlength="3" maxlength="60"')+'</div><label class="field">Business type<select name="businessType"><option '+(d.businessType==='Individual'?'selected':'')+'>Individual</option><option '+(d.businessType==='Registered business'?'selected':'')+'>Registered business</option></select></label>':step===2?'<h2>A home for your operations.</h2><p class="muted small">Choose where you pack and hand over your products.</p><div class="two-col"><label class="field">Region<select name="region" id="seller-region">'+Object.keys(cities).map(r=>'<option '+(r===d.region?'selected':'')+'>'+r+'</option>').join('')+'</select></label><label class="field">City<select name="city" id="seller-city">'+cities[d.region||'Greater Accra'].map(c=>'<option '+(c===d.city?'selected':'')+'>'+c+'</option>').join('')+'</select></label></div>'+sellerField('Business address','address',d.address||'','text','required minlength="5" maxlength="180"')+'<label class="field">Main product category<select name="category">'+categories.map(c=>'<option '+(c[1]===d.category?'selected':'')+'>'+c[1]+'</option>').join('')+'</select></label>'+sellerField('Business registration reference (sample, optional)','registration',d.registration||'','text','maxlength="60"'):'<h2>Finish with the essentials.</h2><div class="notice">Demo setup only. No identity verification or payout account is opened. Never enter bank account numbers or real identity documents here.</div><label class="field">Preferred payout method<select name="payout"><option '+(d.payout==='Mobile Money'?'selected':'')+'>Mobile Money</option><option '+(d.payout==='Bank transfer'?'selected':'')+'>Bank transfer</option></select></label>'+sellerField('Account display name (sample)','payoutName',d.payoutName||d.ownerName||'','text','required maxlength="70"')+'<label class="seller-check"><input type="checkbox" name="guidelines" required> I have reviewed the demo selling guidelines: accurate listings, available stock, careful packaging and timely order updates.</label><label class="seller-check"><input type="checkbox" name="terms" required> I understand this creates a browser-local demo store, not a verified seller account.</label>';return '<div class="crumbs"><a href="#/sell">Sell on Kstore</a> / Create your store</div><div class="seller-onboarding"><aside><span class="eyebrow">A SPACE FOR YOUR AMBITION</span><h1>Let’s make<br>it official.</h1><p class="muted">A few details today.<br>New possibilities tomorrow.</p><ol>'+['Your store','Business details','Preferences & guidelines'].map((t,i)=>'<li class="'+(step===i+1?'active':'')+'">'+t+'</li>').join('')+'</ol><p class="small muted">Your progress is saved in this browser after each step.</p></aside><form class="panel" id="seller-onboard-form"><span class="small muted">STEP '+step+' OF 3</span>'+fields+'<div class="seller-form-actions">'+(step>1?'<button type="button" class="secondary" data-seller="onboard-back">← Back</button>':'<a href="#/sell" class="secondary">Back to selling</a>')+'<button class="primary">'+(step<3?'Save & continue →':'Create demo store →')+'</button></div></form></div>'}
function sellerField(label,name,value,type='text',attrs=''){return '<label class="field">'+label+'<input type="'+type+'" name="'+name+'" value="'+esc(value)+'" '+attrs+'></label>'}
function sellerOrders(){return state.orders.filter(o=>o.lines.some(l=>getP(l.id)?.sellerId===state.seller?.id))}
function sellerOrderLines(o){return o.lines.filter(l=>getP(l.id)?.sellerId===state.seller?.id)}
function sellerOrderStatus(o){return ['Cancelled','Return requested','Refunded'].includes(o.status)?o.status:o.sellerFulfillment?.[state.seller?.id]||o.status}
function sellerRevenue(){return sellerOrders().filter(o=>!['Cancelled','Return requested','Refunded'].includes(sellerOrderStatus(o))).reduce((s,o)=>s+sellerOrderLines(o).reduce((n,l)=>n+l.price*l.qty,0),0)}
function sellerDashboard(tab){const s=state.seller;return '<div class="crumbs"><a href="#/sell">Sell on Kstore</a> / Seller center</div><div class="seller-layout"><aside class="seller-sidebar panel"><div class="seller-store-badge">'+esc(s.shopName.slice(0,1).toUpperCase())+'</div><h3>'+esc(s.shopName)+'</h3><span class="status">Demo store active</span><nav>'+sellerTabs.map(([v,t])=>'<a class="'+(v===tab?'active':'')+'" href="#/seller'+(v?'/'+v:'')+'">'+t+'</a>').join('')+'</nav><a class="small" href="#/seller/store/'+s.id+'">View storefront ↗</a></aside><section class="seller-workspace"><div class="seller-workspace-head"><div><span class="eyebrow">SELLER CENTER</span><h1>'+({products:'Your products',orders:'Your orders',finance:'Your finances',settings:'Store settings',learning:'A little knowledge. A lot of possibility.'}[tab]||'Hello, '+esc(s.ownerName.split(' ')[0])+'.')+'</h1></div><a href="#/seller/products/new" class="primary">＋ Add product</a></div><div class="seller-demo-note">Browser-local demo · Listings and orders are visible in this browser. Payouts and shipments are simulated.</div>'+sellerDashboardBody(tab)+'</section></div>'}
function sellerDashboardBody(tab){const s=state.seller;if(tab==='products')return sellerProducts();if(tab==='orders')return sellerOrderList();if(tab==='finance')return sellerFinance();if(tab==='settings')return sellerSettings();if(tab==='learning')return sellerLearning();const orders=sellerOrders(),revenue=sellerRevenue(),active=s.listings.filter(l=>l.status==='active').length,low=s.listings.filter(l=>l.variants.reduce((n,v)=>n+Number(v.stock),0)<=5).length;return '<p class="muted">Here’s how your store is doing today.</p><div class="seller-metrics">'+[['Active products',active],['Orders to process',orders.filter(o=>sellerOrderStatus(o)==='Processing').length],['Demo gross sales',money(revenue)],['Low-stock listings',low]].map(([t,v])=>'<div class="panel"><small>'+t+'</small><strong>'+v+'</strong></div>').join('')+'</div><div class="seller-home-grid"><div class="panel"><div class="section-head"><h2>Your launch checklist</h2><span class="status">'+(s.listings.length?'3':'2')+' of 3</span></div><div class="seller-task complete">✓ <span>Set up your store profile</span></div><div class="seller-task complete">✓ <span>Review seller guidelines</span></div><a class="seller-task '+(s.listings.length?'complete':'')+'" href="#/seller/products/new">'+(s.listings.length?'✓':'＋')+' <span>Publish your first product</span> →</a></div><div class="panel"><span class="eyebrow">MAKE A STRONG FIRST IMPRESSION</span><h2>A listing worth<br>a closer look.</h2><p class="muted small">Clear photos, useful details and accurate stock help shoppers choose with confidence.</p><a href="#/seller/learning" class="small">Explore seller guides →</a></div></div><div class="panel section"><div class="section-head"><h2>Recent orders</h2><a href="#/seller/orders">View all →</a></div>'+(orders.length?orders.slice(0,3).map(sellerOrderRow).join(''):sellerEmpty('Your first order starts here.','Add a product, then place a demo purchase from its storefront to see the order arrive.'))+'</div>'}
function sellerEmpty(t,d){return '<div class="seller-empty"><span>◇</span><h3>'+t+'</h3><p>'+d+'</p></div>'}
function sellerProducts(){const items=state.seller.listings;return '<div class="panel"><div class="seller-list-toolbar"><input id="seller-product-search" placeholder="Search product name or SKU" aria-label="Search seller products"><select id="seller-product-status" aria-label="Listing status"><option value="">All statuses</option><option value="active">Active</option><option value="draft">Draft</option><option value="paused">Paused</option><option value="archived">Archived</option></select></div><div id="seller-product-results">'+(items.length?'<div class="seller-table-wrap"><table class="seller-table"><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+items.map(l=>'<tr data-listing="'+l.id+'" data-name="'+esc((l.name+' '+l.sku).toLowerCase())+'" data-status="'+l.status+'"><td><div class="seller-product-cell"><img src="'+l.images[0]+'" alt=""><span><b>'+esc(l.name)+'</b><small>'+esc(l.sku)+' · '+l.variants.length+' variations</small></span></div></td><td>'+money(l.price)+'</td><td>'+l.variants.reduce((s,v)=>s+Number(v.stock),0)+'</td><td><span class="status '+(l.status==='active'?'':'neutral')+'">'+l.status+'</span></td><td><div class="seller-row-actions"><button data-seller="edit-product" data-id="'+l.id+'">Edit</button><button data-seller="toggle-listing" data-id="'+l.id+'">'+(l.status==='active'?'Pause':'Publish')+'</button><button data-seller="archive-listing" data-id="'+l.id+'">Archive</button></div><a class="small" href="#/product/'+l.id+'">Preview ↗</a></td></tr>').join('')+'</tbody></table></div><p id="seller-search-empty" hidden class="muted small">No matching products.</p>':sellerEmpty('Your next bestseller belongs here.','Add your first product with clear photos, a fair price and accurate stock.'))+'</div></div>'}
function sellerOrderRow(o){const status=sellerOrderStatus(o),lines=sellerOrderLines(o),gross=lines.reduce((s,l)=>s+l.price*l.qty,0);return '<article class="seller-order"><div class="section-head"><div><h3>'+o.id+'</h3><span class="muted small">'+o.date+' · '+lines.reduce((s,l)=>s+l.qty,0)+' items</span></div><span class="status">'+esc(status)+'</span></div>'+lines.map(l=>'<div class="summary-row"><span>'+esc(getP(l.id).name)+'<small class="muted"> · '+esc(l.variant)+' × '+l.qty+'</small></span><b>'+money(l.price*l.qty)+'</b></div>').join('')+'<p class="small muted">Demo delivery: '+esc(o.destination)+'</p><div class="seller-order-bottom"><b>'+money(gross)+'</b><div class="order-actions">'+(status==='Processing'?'<button class="primary" data-seller="order-status" data-id="'+o.id+'" data-value="Packed">Mark packed</button>':status==='Packed'?'<button class="primary" data-seller="order-status" data-id="'+o.id+'" data-value="Shipped">Mark shipped</button>':status==='Shipped'?'<button class="primary" data-seller="order-status" data-id="'+o.id+'" data-value="Delivered">Simulate delivery</button>':status==='Return requested'?'<button class="secondary" data-seller="order-status" data-id="'+o.id+'" data-value="Refunded">Approve demo refund</button>':'')+'<button class="secondary" data-seller="packing-slip" data-id="'+o.id+'">Packing slip</button></div></div></article>'}
function sellerOrderList(){const orders=sellerOrders();return '<div class="panel"><div class="seller-list-toolbar"><h3>'+orders.length+' orders</h3><select id="seller-order-filter" aria-label="Filter seller orders"><option value="">All orders</option>'+['Processing','Packed','Shipped','Delivered','Cancelled','Return requested','Refunded'].map(s=>'<option>'+s+'</option>').join('')+'</select></div>'+(orders.length?'<div id="seller-orders-list">'+orders.map(o=>'<div data-order-status="'+sellerOrderStatus(o)+'">'+sellerOrderRow(o)+'</div>').join('')+'</div>':sellerEmpty('Good things are on their way.','Orders containing your listings will appear here after a demo checkout.'))+'</div>'}
function sellerFinance(){const orders=sellerOrders().filter(o=>!['Cancelled','Return requested','Refunded'].includes(sellerOrderStatus(o))),gross=orders.reduce((s,o)=>s+sellerOrderLines(o).reduce((n,l)=>n+l.price*l.qty,0),0),fees=Math.round(gross*.05*100)/100;return '<div class="seller-metrics"><div class="panel"><small>Demo gross sales</small><strong>'+money(gross)+'</strong></div><div class="panel"><small>Sample commission · 5%</small><strong>'+money(fees)+'</strong></div><div class="panel"><small>Estimated demo net</small><strong>'+money(gross-fees)+'</strong></div></div><div class="notice">Illustration only. The 5% commission is a demo assumption. No payable balance, actual settlement or money transfer is created.</div><div class="panel"><div class="section-head"><h2>Transaction overview</h2><button class="secondary" data-seller="export-finance">Export CSV</button></div>'+(orders.length?'<div class="seller-table-wrap"><table class="seller-table"><thead><tr><th>Order</th><th>Status</th><th>Gross</th><th>Sample fee</th><th>Demo net</th></tr></thead><tbody>'+orders.map(o=>{const n=sellerOrderLines(o).reduce((s,l)=>s+l.price*l.qty,0);return '<tr><td>'+o.id+'</td><td>'+sellerOrderStatus(o)+'</td><td>'+money(n)+'</td><td>'+money(n*.05)+'</td><td>'+money(n*.95)+'</td></tr>'}).join('')+'</tbody></table></div>':sellerEmpty('A fresh start.','Your demo transaction summary will appear after your first sale.'))+'</div>'}
function sellerLearning(){return '<div class="seller-guide-grid">'+[['01','Create a listing shoppers can trust','Use a specific title, accurate category, useful description and clear photos. Photograph the actual item from multiple angles. Avoid misleading brand claims.'],['02','Price and stock with care','Set a positive selling price. Only show a reference price when it is higher and accurate. Add each size or color as a unique variation with whole-number stock.'],['03','Pack it like it matters','Check the chosen variation, protect the product, include a packing slip and update the order to Packed when ready.'],['04','Keep shoppers in the loop','Move an order to Shipped only when handed over. In this demo you can simulate delivery. Live shipping needs a carrier connection.'],['05','Handle returns thoughtfully','Review return requests, follow your published policy and record the decision. A demo refund changes status only; it does not move money.'],['06','Understand your finances','Check sales, sample fees and estimated net. Real payouts require verification, a payment provider and an agreed fee schedule.']].map(([n,t,d])=>'<article class="panel"><span class="eyebrow">GUIDE '+n+'</span><h3>'+t+'</h3><p class="muted small">'+d+'</p></article>').join('')+'</div>'}
function sellerSettings(){const s=state.seller;return '<form id="seller-settings-form" class="panel"><h2>Your store, your story.</h2><div class="two-col">'+sellerField('Store name','shopName',s.shopName,'text','required minlength="3" maxlength="60"')+sellerField('Contact phone','phone',s.phone,'tel','required pattern="[0-9+ ()-]{9,16}"')+'</div><label class="field">Store description<textarea name="description" maxlength="500" rows="4">'+esc(s.description||'')+'</textarea></label>'+sellerField('Operating address','address',s.address,'text','required minlength="5" maxlength="180"')+'<label class="field">Payout preference<select name="payout"><option '+(s.payout==='Mobile Money'?'selected':'')+'>Mobile Money</option><option '+(s.payout==='Bank transfer'?'selected':'')+'>Bank transfer</option></select></label><p class="small muted">No actual payout account is connected. Seller account email is the email used during onboarding.</p><button class="primary">Save store settings</button></form>'}
function sellerStore(){if(!state.seller)return notFound();const s=state.seller,items=s.listings.filter(l=>l.status==='active').map(l=>getP(l.id));return '<div class="crumbs"><a href="#/catalog">Shop</a> / '+esc(s.shopName)+'</div><section class="seller-store-hero"><span class="seller-store-badge">'+esc(s.shopName.slice(0,1).toUpperCase())+'</span><div><span class="status">Kstore demo seller</span><h1>'+esc(s.shopName)+'</h1><p>'+esc(s.description||'Thoughtful finds, selected for your everyday.')+'</p><span class="small muted">'+esc(s.city)+', '+esc(s.region)+'</span></div></section><div class="section-head section"><h2>Shop this store</h2><span class="muted small">'+items.length+' products</span></div>'+(items.length?'<div class="product-grid catalog-grid">'+items.map(card).join('')+'</div>':empty('New finds are on the way','This store has no active listings yet.'))}
function sellerListingEditor(id){const l=state.seller.listings.find(l=>l.id===id)||{};sellerSession.images=[...(l.images||[])];modal(id?'Edit product':'Create your next bestseller','<form id="seller-product-form"><input type="hidden" name="listingId" value="'+esc(id||'')+'">'+sellerField('Product title','name',l.name||'','text','required minlength="5" maxlength="140"')+'<div class="two-col">'+sellerField('SKU','sku',l.sku||'','text','required maxlength="50"')+sellerField('Brand (optional)','brand',l.brand||'','text','maxlength="50"')+'</div><div class="two-col"><label class="field">Category<select name="category">'+categories.map(c=>'<option '+(c[1]===(l.category||state.seller.category)?'selected':'')+'>'+c[1]+'</option>').join('')+'</select></label><label class="field">Condition<select name="condition"><option '+(l.condition==='New'?'selected':'')+'>New</option><option '+(l.condition==='Refurbished'?'selected':'')+'>Refurbished</option></select></label></div><label class="field">Description<textarea name="description" rows="3" required minlength="20" maxlength="3000">'+esc(l.description||'')+'</textarea></label><div class="two-col">'+sellerField('Selling price (GH₵)','price',l.price||'','number','required min="0.01" step="0.01"')+sellerField('Reference price (optional)','old',l.old||'','number','min="0.01" step="0.01"')+'</div><h3 class="small">PRODUCT PHOTOS · UP TO 6</h3><p class="small muted">Add photos of the actual product. Uploads are resized and saved in this browser.</p><input type="file" id="seller-photo-upload" accept="image/jpeg,image/png,image/webp" multiple aria-label="Upload product photos"><div class="inline" style="margin-top:10px"><input type="url" id="seller-photo-url" placeholder="Or paste an HTTPS image URL" aria-label="Product photo URL"><button type="button" class="secondary" data-seller="add-photo-url">Add URL</button></div><div id="seller-image-list"></div><h3 class="small">VARIATIONS & STOCK</h3><p class="small muted">Use unique labels such as Black / EU 42. Stock must be a whole number.</p><div id="seller-variant-rows">'+(l.variants||[{name:'Standard',stock:1}]).map(v=>sellerVariantRow(v)).join('')+'</div><button type="button" class="secondary" data-seller="add-variant">＋ Add variation</button><label class="field">Listing status<select name="status"><option value="draft" '+(l.status!=='active'?'selected':'')+'>Draft</option><option value="active" '+(l.status==='active'?'selected':'')+'>Publish in demo catalog</option></select></label><p id="seller-product-error" class="error" role="alert"></p><button class="primary full" id="seller-product-save">Save product</button></form>');$('#modal').classList.add('seller-editor');sellerImageList()}
function sellerVariantRow(v={name:'',stock:0}){return '<div class="seller-variant-row"><label class="field">Variation<input name="variantName" required maxlength="60" value="'+esc(v.name)+'"></label><label class="field">Stock<input name="variantStock" type="number" min="0" max="100000" step="1" required value="'+v.stock+'"></label><button type="button" data-seller="remove-variant" aria-label="Remove variation">×</button></div>'}
function sellerImageList(){$('#seller-image-list').innerHTML=sellerSession.images.map((src,i)=>'<div><img src="'+src+'" alt="Product photo '+(i+1)+'"><span>'+(i===0?'Main photo':'Photo '+(i+1))+'</span><button type="button" data-seller="remove-photo" data-index="'+i+'" aria-label="Remove photo '+(i+1)+'">×</button>'+(i>0?'<button type="button" data-seller="main-photo" data-index="'+i+'" class="small">Make main</button>':'')+'</div>').join('')}
function sellerFilterProducts(){const q=$('#seller-product-search').value.toLowerCase(),status=$('#seller-product-status').value;let n=0;$$('[data-listing]').forEach(r=>{r.hidden=!(r.dataset.name.includes(q)&&(!status||r.dataset.status===status));if(!r.hidden)n++});if($('#seller-search-empty'))$('#seller-search-empty').hidden=n>0}
function sellerDownload(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(s){const text=String(s??'');return '"'+(/^[=+@-]/.test(text)?"'":'')+text.replaceAll('"','""')+'"'}
document.addEventListener('click',e=>{const b=e.target.closest('[data-seller]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.seller,id=b.dataset.id,v=b.dataset.value;if(a==='onboard-back'){sellerSession.step=Math.max(1,sellerSession.step-1);sellerSession.draft.step=sellerSession.step;if(state.seller){state.seller.application={...sellerSession.draft};sellerSave()}render();return}if(!sellerLive())return toast('Open your demo seller account to continue.');if(a==='edit-product')return sellerListingEditor(id);if(a==='toggle-listing'){const l=state.seller.listings.find(l=>l.id===id);l.status=l.status==='active'?'paused':'active';if(!sellerSave())return;syncSellerProducts();render();toast('Listing '+l.status);return}if(a==='archive-listing')return modal('Archive this listing?','<p>It will leave the demo catalog. Existing order records will be kept.</p><button class="primary" data-seller="confirm-archive" data-id="'+id+'">Archive listing</button>');if(a==='confirm-archive'){state.seller.listings.find(l=>l.id===id).status='archived';sellerSave();syncSellerProducts();render();return}if(a==='add-variant'){$('#seller-variant-rows').insertAdjacentHTML('beforeend',sellerVariantRow());return}if(a==='remove-variant'){if($$('.seller-variant-row').length>1)b.closest('.seller-variant-row').remove();else toast('Keep at least one variation.');return}if(a==='add-photo-url'){const raw=$('#seller-photo-url').value.trim();try{const u=new URL(raw);if(u.protocol!=='https:')throw Error();if(sellerSession.images.length>=6)return toast('You can add up to six photos.');sellerSession.images.push(u.href);$('#seller-photo-url').value='';sellerImageList()}catch{toast('Use a valid HTTPS image URL.')}return}if(a==='remove-photo'){sellerSession.images.splice(Number(b.dataset.index),1);sellerImageList();return}if(a==='main-photo'){const [image]=sellerSession.images.splice(Number(b.dataset.index),1);sellerSession.images.unshift(image);sellerImageList();return}if(a==='order-status'){const o=sellerOrders().find(o=>o.id===id);const next=b.dataset.value,allowed={Processing:'Packed',Packed:'Shipped',Shipped:'Delivered','Return requested':'Refunded'};if(!o||allowed[sellerOrderStatus(o)]!==next)return toast('This order status has changed.');o.sellerFulfillment=o.sellerFulfillment||{};o.sellerFulfillment[state.seller.id]=next;if(o.lines.every(l=>getP(l.id)?.sellerId===state.seller.id))o.status=next;if(next==='Refunded'){o.sellerRefunds=o.sellerRefunds||{};o.sellerRefunds[state.seller.id]=true;if(o.lines.every(l=>getP(l.id)?.sellerId===state.seller.id))o.paymentStatus='Simulated refund completed';}if(!sellerSave())return;render();toast('Demo order marked '+next.toLowerCase());return}if(a==='packing-slip'){const o=sellerOrders().find(o=>o.id===id);return sellerDownload('packing-slip-'+o.id+'.txt','KSTORE DEMO PACKING SLIP\nStore: '+state.seller.shopName+'\nOrder: '+o.id+'\nDate: '+o.date+'\nDestination: '+o.destination+'\n\n'+sellerOrderLines(o).map(l=>getP(l.id).name+' | '+l.variant+' | Qty '+l.qty).join('\n')+'\n\nDEMO ONLY — no carrier label or shipment booking.','text/plain')}if(a==='export-finance'){const rows=[['Order','Date','Status','Gross GHS','Sample fee GHS','Estimated net GHS']];sellerOrders().filter(o=>!['Cancelled','Return requested','Refunded'].includes(sellerOrderStatus(o))).forEach(o=>{const n=sellerOrderLines(o).reduce((s,l)=>s+l.price*l.qty,0);rows.push([o.id,o.date,o.status,n.toFixed(2),(n*.05).toFixed(2),(n*.95).toFixed(2)])});sellerDownload('kstore-demo-finances.csv',rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');return}},true);
document.addEventListener('input',e=>{if(['seller-product-search','seller-product-status'].includes(e.target.id))sellerFilterProducts()});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='seller-region')$('#seller-city').innerHTML=cities[el.value].map(c=>'<option>'+c+'</option>').join('');if(el.id==='seller-product-status')sellerFilterProducts();if(el.id==='seller-order-filter')$$('[data-order-status]').forEach(r=>r.hidden=!!el.value&&r.dataset.orderStatus!==el.value);if(el.id==='seller-photo-upload'){const button=$('#seller-product-save');button.disabled=true;try{for(const file of el.files){if(sellerSession.images.length>=6){toast('Maximum six photos per listing.');break}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Use JPG, PNG or WebP up to 10 MB.');continue}const bitmap=await createImageBitmap(file);const scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);sellerSession.images.push(canvas.toDataURL('image/jpeg',.78));bitmap.close()}sellerImageList()}catch{toast('That image could not be processed. Try another photo.')}finally{button.disabled=false;el.value=''}}});
document.addEventListener('submit',e=>{const f=e.target,formId=f.getAttribute('id');if(!formId?.startsWith('seller-'))return;e.preventDefault();e.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f));if(formId==='seller-onboard-form'){const step=sellerSession.step;if(step===1){if(!d.ownerName.trim()||!d.shopName.trim())return toast('Enter your name and store name.');if(state.user&&state.user.email!==d.email.trim())return toast('Use the signed-in demo account email, or sign out first.');sellerSession.draft={...sellerSession.draft,...d};if(!state.user)state.user={name:d.ownerName.trim(),email:d.email.trim()};state.seller=state.seller||{id:'store-'+Date.now(),ownerEmail:d.email.trim(),status:'draft',listings:[]};}else sellerSession.draft={...sellerSession.draft,...d};if(step===2&&!cities[d.region]?.includes(d.city))return toast('Choose a valid city.');if(step<3){sellerSession.step=step+1;sellerSession.draft.step=step+1;state.seller.application={...sellerSession.draft};if(sellerSave())render();return}if(!d.guidelines||!d.terms)return toast('Review the guidelines and demo acknowledgment.');Object.assign(state.seller,sellerSession.draft,{status:'active',ownerName:sellerSession.draft.ownerName.trim(),shopName:sellerSession.draft.shopName.trim(),createdAt:new Date().toISOString(),description:'',application:undefined});delete state.seller.step;if(!sellerSave())return;go('/seller');toast('Your demo store is ready. Let’s add your first product.');return}if(!sellerLive())return toast('Sign in to your seller account.');if(formId==='seller-product-form'){const fail=t=>$('#seller-product-error').textContent=t,price=Number(d.price),old=Number(d.old)||price;const variants=$$('.seller-variant-row',f).map(r=>({name:$('[name=variantName]',r).value.trim(),stock:Number($('[name=variantStock]',r).value)}));if(!d.name.trim()||!d.sku.trim()||d.description.trim().length<20)return fail('Add a title, SKU and description of at least 20 characters.');if(!(price>0)||!Number.isFinite(price)||old<price)return fail('Price must be positive and reference price cannot be lower.');if(!sellerSession.images.length)return fail('Add at least one product photo.');if(variants.some(v=>!v.name||!Number.isInteger(v.stock)||v.stock<0)||new Set(variants.map(v=>v.name.toLowerCase())).size!==variants.length)return fail('Use unique variation names and non-negative whole-number stock.');if(state.seller.listings.some(l=>l.sku.toLowerCase()===d.sku.trim().toLowerCase()&&l.id!==d.listingId))return fail('This SKU is already used by another listing.');const l={id:d.listingId||'seller-'+Date.now(),name:d.name.trim(),sku:d.sku.trim(),brand:d.brand.trim(),description:d.description.trim(),category:d.category,condition:d.condition,price,old,variants,images:[...sellerSession.images],status:d.status,updatedAt:new Date().toISOString()};const before=[...state.seller.listings],idx=before.findIndex(x=>x.id===l.id);if(idx>=0)state.seller.listings[idx]=l;else state.seller.listings.push(l);if(!sellerSave()){state.seller.listings=before;return fail('Storage is full. Remove some photos and try again.')}syncSellerProducts();if(route().path==='/seller/products/new')go('/seller/products');else render();toast('Product saved'+(l.status==='active'?' and published in your demo catalog.':' as a draft.'));return}if(formId==='seller-settings-form'){Object.assign(state.seller,{shopName:d.shopName.trim(),phone:d.phone.trim(),description:d.description.trim(),address:d.address.trim(),payout:d.payout});if(sellerSave()){syncSellerProducts();render();toast('Store settings saved')}}},true);
$('#modal').addEventListener('close',()=>$('#modal').classList.remove('seller-editor'));

// Reserve seller inventory only after the existing checkout creates a demo order.
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="place-order"],[data-action="confirm-cancel"]');if(!b||!state.seller)return;if(b.dataset.action==='place-order'&&state.cart.some(l=>{const p=getP(l.id);return p?.sellerId&&(p.listingStatus!=='active'||l.qty>variantStock(p,l.variant))})){e.preventDefault();e.stopImmediatePropagation();toast('A seller listing has changed. Recheck your cart before checkout.');return}const before=state.orders.length,old=b.dataset.value?state.orders.find(o=>o.id===b.dataset.value):null,oldStatus=old?.status;queueMicrotask(()=>{if(b.dataset.action==='place-order'&&state.orders.length===before+1){const o=state.orders[0];for(const line of o.lines){const listing=state.seller.listings.find(l=>l.id===line.id),v=listing?.variants.find(v=>v.name===line.variant);if(v)v.stock=Math.max(0,Number(v.stock)-line.qty)}sellerSave();syncSellerProducts()}if(b.dataset.action==='confirm-cancel'&&old&&oldStatus!=='Cancelled'&&old.status==='Cancelled'){for(const line of old.lines){const l=state.seller.listings.find(l=>l.id===line.id),v=l?.variants.find(v=>v.name===line.variant);if(v)v.stock=Number(v.stock)+line.qty}sellerSave();syncSellerProducts()}})},true);

const baseOrderDetail=orderDetail;orderDetail=function(o){baseOrderDetail(o);if(o.sellerFulfillment&&state.seller)$('#modal').insertAdjacentHTML('beforeend','<h3>Seller fulfillment</h3><p class="small">'+esc(state.seller.shopName)+': '+esc(sellerOrderStatus(o))+'</p>')};
const baseRender=render;render=function(){syncSellerProducts();baseRender();if(route().path==='/seller/products/new'&&sellerLive())sellerListingEditor();};
/* Firebase UI bootstraps the complete app. */
